using System.Text.RegularExpressions;
partial class Program{
static string SourceRoot(){var configured=Environment.GetEnvironmentVariable("TOHS_VERSION_SOURCE");if(!string.IsNullOrWhiteSpace(configured))return configured;var p=new DirectoryInfo(AppContext.BaseDirectory);while(p!=null&&!File.Exists(Path.Combine(p.FullName,"TownOfHost.csproj")))p=p.Parent;return p?.FullName??throw new Exception("source root not found");}
static string Source(string file)=>File.ReadAllText(Path.Combine(SourceRoot(),file));
static void RunSourceBoundaries(){
foreach(var file in new[]{"Patches/GameStartManagerPatch.cs","Patches/AutoStartWhenTimerLowPatch.cs"})Test("YouTube map hook removed from "+file,()=>Check(!Source(file).Contains("YouTubeMapVote.ApplyAtGameStart")));
foreach(var file in new[]{"Patches/PlayerJoinAndLeftPatch.cs","Patches/onGameStartedPatch.cs"})Test("no comment-admission or game-name association in "+file,()=>{var s=Source(file);foreach(var token in new[]{"StreamerInfo.JoinPlayer(","StreamerInfo.LeftPlayer(","StreamerInfo.ChangeList("})Check(!s.Contains(token));});
Test("ordinary map selection and other admission protections retained",()=>{Check(Source("Patches/GameStartManagerPatch.cs").Contains("SelectRandomMap();")&&Source("Patches/GameStartManagerPatch.cs").Contains("SelectRandomPreset();"));var s=Source("Patches/PlayerJoinAndLeftPatch.cs");Check(s.Contains("BanManager.CheckWhiteList")&&s.Contains("BanManager.CheckDenyNamePlayer"));});
Test("legacy option IDs retained but hidden",()=>{var s=Source("Modules/OptionHolder.cs");foreach(var id in new[]{"1_400_164","1_400_171"}){int p=s.IndexOf("BooleanOptionItem.Create("+id);Check(p>=0&&s.Substring(p,Math.Min(230,s.Length-p)).Contains(".SetHidden(true)"));}});
Test("retired toggles absent from fetch and HUD paths",()=>{Check(!Source("Modules/Streamer/Readcomment.cs").Contains("JoinByCommentOnly")&&!Source("Modules/Streamer/Readcomment.cs").Contains("YouTubeMapVote"));Check(!Source("Modules/Streamer/StreamCommentFrame.cs").Contains("YouTubeMapVote"));});
Test("comment position reset binding is preserved",()=>Check(Source("Modules/Streamer/StreamerMenu.cs").Contains("() => StreamCommentFrame.ResetPosition()")));
Test("actual UI never displays a game identity or raw channel ID",()=>{var s=Source("Modules/Streamer/StreamerHopeMenu.cs");foreach(var forbidden in new[]{"PlayerName","AccountID","Channel","KickPlayer","JoinGame("})Check(!s.Contains(forbidden));});
Test("no player identity or comment body stored by interest model",()=>{var s=Source("Modules/Streamer/StreamInterestList.cs");Check(!s.Contains("PlayerName")&&!s.Contains("PlayerId")&&!s.Contains("FriendCode")&&!s.Contains("Main.NormalOptions"));});
Test("legacy API and HTML acquisition no longer executable",()=>{foreach(var f in new[]{"Modules/Streamer/Readcomment.cs","Modules/Streamer/StreamSafety.cs","Modules/Streamer/ChatData.cs"}){var s=Source(f);foreach(var forbidden in new[]{"youtubei/","ytInitialData","INNERTUBE_API_KEY","StreamCommentParser","new HttpRequestMessage("})Check(!s.Contains(forbidden));}});
Test("only official API origins in source",()=>{var s=Source("Modules/Streamer/YouTubeOfficialApi.cs");Check(s.Contains("https://www.googleapis.com/youtube/v3/videos?")&&s.Contains("https://youtube.googleapis.com/youtube.api.v3.V3DataLiveChatMessageService/StreamList"));Check(!s.Contains("www.youtube.com/live_chat"));});
Test("readonly OAuth scope and no automatic browser or listener",()=>{var s=Source("Modules/Streamer/YouTubeDesktopOAuth.cs");Check(s.Contains("youtube.readonly")&&!s.Contains("Process.Start(")&&!s.Contains("HttpListener")&&!s.Contains("File.Write"));});
Test("privacy and terms links are user-initiated",()=>{var s=Source("Modules/Streamer/StreamerMenu.cs");Check(s.Contains("() => Application.OpenURL(YouTubeOfficialRuntime.TermsUrl)")&&s.Contains("() => Application.OpenURL(YouTubeOfficialRuntime.PrivacyUrl)"));});
Test("frame formatter fixture matches production method",()=>{
 string Body(string text){int pos=text.IndexOf("string BuildText()",StringComparison.Ordinal);Check(pos>=0);int start=text.IndexOf('{',pos),level=0;for(int n=start;n<text.Length;n++){if(text[n]=='{')level++;if(text[n]=='}'&&--level==0)return Regex.Replace(text.Substring(start,n-start+1),@"\s+", " ");}throw new Exception("unclosed formatter");}
 Check(Body(Source("Modules/Streamer/StreamCommentFrame.cs"))==Body(Source("tests/Streaming43505.Tests/GeneratedFrameText.cs")));
});
Test("Google auth UI binds explicit user actions and hides cleanly",()=>{var s=Source("Modules/Streamer/YouTubeAuthMenu.cs");foreach(var action in new[]{"() => YouTubeAuthRuntime.Begin()","() => YouTubeAuthRuntime.Unlink()","() => YouTubeAuthRuntime.Cancel()","YouTubeOfficialRuntime.PermissionUrl","nameof(MainMenuManager.LateUpdate)","service.ConsumeRestart()","StreamerInfo.HasConnectionError","StreamerInfo.StatusMessage"})Check(s.Contains(action));Check(s.Contains("root.SetActive(false)")&&s.Contains("YouTubeAuthRuntime.Cancel(); root.SetActive(false)"));});
Test("authorization never enables comments or participation policy",()=>{foreach(var file in new[]{"Modules/Streamer/YouTubeAuthMenu.cs","Modules/Streamer/YouTubeAuthService.cs","Modules/Streamer/YouTubeLoopbackOAuth.cs"}){var s=Source(file);Check(!s.Contains("ShowStreamComments.Value =")&&!s.Contains("ParticipationPolicyReviewed = true")&&!s.Contains("Logger.Warn(error")&&!s.Contains("Logger.Warn(ex."));}});
Test("comment keywords no longer request game name",()=>{var s=Source("Resources/string.csv");Check(!s.Contains("参加ワード<size=30%>(+プレイヤー名)"));Check(s.Contains("参加希望キーワード")&&s.Contains("希望者一覧を初期化"));});
}
}
